from __future__ import annotations; import pytest; from common.meta.base.gate_cli import REPO_ROOT; from common.meta.extension import check_tier_ast_literal; from common.testing import check_package_migration_safety as safety_gate
def test_clean_tree_package_migration_safety_passes() -> None: assert safety_gate.violations(REPO_ROOT) == []; assert safety_gate.main(['--repo-root', str(REPO_ROOT)]) == 0; assert safety_gate.main(['--definitely-invalid']) == 2
def test_package_migration_safety_catches_subgate_violation(monkeypatch: pytest.MonkeyPatch) -> None: sentinel = 'synthetic-error: package tier is not a literal'; monkeypatch.setattr(check_tier_ast_literal, 'violations', lambda repo_root: [sentinel]); violations = safety_gate.violations(REPO_ROOT); assert sentinel in violations; assert safety_gate.main(['--repo-root', str(REPO_ROOT)]) == 1
